        for (int end = 0; end < s.length(); end++) {
            char current = s.charAt(end);
            if (lastSeen.containsKey(current) && lastSeen.get(current) >= start) start = lastSeen.get(current) + 1;
            lastSeen.put(current, end);
            best = Math.max(best, end - start + 1);
        }
        return best;
    }
}

