class Solution:
    def totalFruit(self, fruits: list[int]) -> int:
        counts: dict[int, int] = {}
        start = best = 0
        for end, fruit in enumerate(fruits):
            counts[fruit] = counts.get(fruit, 0) + 1
            while len(counts) > 2:
                leaving = fruits[start]
                counts[leaving] -= 1
                if counts[leaving] == 0:
                    del counts[leaving]
                start += 1
            best = max(best, end - start + 1)
        return best

java.code:
class Solution {
    public int totalFruit(int[] fruits) {
        Map<Integer, Integer> counts = new HashMap<>();
        int start = 0, best = 0;
        for (int end = 0; end < fruits.length; end++) {
            counts.put(fruits[end], counts.getOrDefault(fruits[end], 0) + 1);
            while (counts.size() > 2) {
                int leaving = fruits[start++];
                counts.put(leaving, counts.get(leaving) - 1);
                if (counts.get(leaving) == 0) counts.remove(leaving);
            }
            best = Math.max(best, end - start + 1);
        }
        return best;
    }
}

