class Solution {
    public void sortColors(int[] nums) {
        int low = 0, current = 0, high = nums.length - 1;
        while (current <= high) {
            if (nums[current] == 0) {
                int value = nums[low]; nums[low] = nums[current]; nums[current] = value;
                low++; current++;
            } else if (nums[current] == 2) {
                int value = nums[current]; nums[current] = nums[high]; nums[high] = value;
                high--;
            } else current++;
        }
    }
}

